import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';

// Animated grid node for background
const GridNode = ({ x, y, delay, pulse }) => (
  <div style={{
    position: 'absolute', left: x, top: y,
    width: 4, height: 4, borderRadius: '50%',
    background: pulse ? '#00d4aa' : 'rgba(0,212,170,0.2)',
    boxShadow: pulse ? '0 0 8px #00d4aa' : 'none',
    animation: `nodePulse ${2 + delay}s ease-in-out ${delay}s infinite`,
    transition: 'all 0.3s',
  }}/>
);

export default function Login() {
  const [email, setEmail]       = useState('');
  const [password, setPassword] = useState('');
  const [showPwd, setShowPwd]   = useState(false);
  const [error, setError]       = useState('');
  const [loading, setLoading]   = useState(false);
  const [focused, setFocused]   = useState(null);
  const [mounted, setMounted]   = useState(false);
  const { login }  = useAuth();
  const navigate   = useNavigate();

  useEffect(() => { setTimeout(() => setMounted(true), 50); }, []);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError('');
    try {
      await login(email, password);
      navigate('/');
    } catch {
      setError('Email ou mot de passe incorrect');
    } finally {
      setLoading(false);
    }
  };

  // Grid nodes positions
  const nodes = [
    {x:'10%',y:'15%',delay:0,pulse:true},
    {x:'25%',y:'40%',delay:0.8,pulse:false},
    {x:'15%',y:'65%',delay:1.5,pulse:true},
    {x:'40%',y:'20%',delay:0.3,pulse:false},
    {x:'35%',y:'75%',delay:1.1,pulse:true},
    {x:'60%',y:'10%',delay:0.6,pulse:false},
    {x:'70%',y:'30%',delay:1.8,pulse:true},
    {x:'80%',y:'55%',delay:0.4,pulse:false},
    {x:'65%',y:'80%',delay:1.3,pulse:true},
    {x:'88%',y:'15%',delay:0.9,pulse:false},
    {x:'92%',y:'70%',delay:1.6,pulse:true},
    {x:'50%',y:'50%',delay:0.2,pulse:false},
  ];

  return (
    <>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Rajdhani:wght@400;500;600;700&family=JetBrains+Mono:wght@300;400;500&display=swap');

        * { box-sizing: border-box; margin: 0; padding: 0; }

        @keyframes nodePulse {
          0%, 100% { opacity: 0.2; transform: scale(1); }
          50% { opacity: 1; transform: scale(1.6); }
        }
        @keyframes lineFlow {
          0% { stroke-dashoffset: 200; opacity: 0; }
          20% { opacity: 1; }
          80% { opacity: 1; }
          100% { stroke-dashoffset: 0; opacity: 0; }
        }
        @keyframes scanline {
          0% { transform: translateY(-100%); }
          100% { transform: translateY(100vh); }
        }
        @keyframes fadeUp {
          from { opacity: 0; transform: translateY(24px); }
          to   { opacity: 1; transform: translateY(0); }
        }
        @keyframes glitch {
          0%,100% { clip-path: inset(0 0 100% 0); }
          10% { clip-path: inset(20% 0 60% 0); transform: translateX(-2px); }
          20% { clip-path: inset(60% 0 10% 0); transform: translateX(2px); }
          30% { clip-path: inset(0 0 0 0); transform: translateX(0); }
        }
        @keyframes borderPulse {
          0%,100% { border-color: rgba(0,212,170,0.3); box-shadow: 0 0 0 rgba(0,212,170,0); }
          50% { border-color: rgba(0,212,170,0.7); box-shadow: 0 0 12px rgba(0,212,170,0.15); }
        }
        @keyframes spin {
          from { transform: rotate(0deg); }
          to   { transform: rotate(360deg); }
        }
        @keyframes dataStream {
          0%   { transform: translateY(0);   opacity: 0; }
          10%  { opacity: 0.4; }
          90%  { opacity: 0.4; }
          100% { transform: translateY(-400px); opacity: 0; }
        }

        .login-bg {
          min-height: 100vh;
          background: #0d1117;
          display: flex;
          align-items: center;
          justify-content: center;
          font-family: 'Rajdhani', sans-serif;
          position: relative;
          overflow: hidden;
        }

        /* Subtle grid texture */
        .login-bg::before {
          content: '';
          position: absolute; inset: 0;
          background-image:
            linear-gradient(rgba(0,212,170,0.03) 1px, transparent 1px),
            linear-gradient(90deg, rgba(0,212,170,0.03) 1px, transparent 1px);
          background-size: 48px 48px;
          pointer-events: none;
        }

        /* Radial glow left side */
        .login-bg::after {
          content: '';
          position: absolute;
          left: -10%; top: 20%;
          width: 500px; height: 500px;
          background: radial-gradient(circle, rgba(0,212,170,0.06) 0%, transparent 70%);
          pointer-events: none;
        }

        .scanline {
          position: absolute;
          left: 0; right: 0;
          height: 2px;
          background: linear-gradient(90deg, transparent, rgba(0,212,170,0.08), transparent);
          animation: scanline 8s linear infinite;
          pointer-events: none;
          z-index: 1;
        }

        /* Left panel — visual / branding */
        .left-panel {
          width: 460px;
          padding: 60px 48px;
          display: flex;
          flex-direction: column;
          justify-content: center;
          position: relative;
        }

        .left-panel .brand-tag {
          font-family: 'JetBrains Mono', monospace;
          font-size: 10px;
          color: #00d4aa;
          letter-spacing: 4px;
          text-transform: uppercase;
          margin-bottom: 32px;
          display: flex;
          align-items: center;
          gap: 8px;
        }
        .left-panel .brand-tag::before {
          content: '';
          display: inline-block;
          width: 20px; height: 1px;
          background: #00d4aa;
        }

        .left-panel h2 {
          font-size: 42px;
          font-weight: 700;
          color: #e8eaf0;
          line-height: 1.1;
          margin-bottom: 16px;
          letter-spacing: 1px;
        }
        .left-panel h2 span { color: #00d4aa; }

        .left-panel p {
          font-size: 14px;
          color: #7a8394;
          line-height: 1.7;
          font-family: 'JetBrains Mono', monospace;
          font-weight: 300;
          margin-bottom: 40px;
        }

        .stat-grid {
          display: grid;
          grid-template-columns: 1fr 1fr;
          gap: 12px;
        }
        .stat-item {
          background: rgba(255,255,255,0.02);
          border: 1px solid rgba(255,255,255,0.06);
          border-radius: 8px;
          padding: 14px 16px;
          position: relative;
          overflow: hidden;
          animation: fadeUp 0.6s ease both;
        }
        .stat-item::before {
          content: '';
          position: absolute; top: 0; left: 0; right: 0; height: 1px;
          background: linear-gradient(90deg, transparent, rgba(0,212,170,0.4), transparent);
        }
        .stat-label {
          font-family: 'JetBrains Mono', monospace;
          font-size: 9px;
          color: #4a5260;
          letter-spacing: 2px;
          text-transform: uppercase;
          margin-bottom: 6px;
        }
        .stat-value {
          font-size: 22px;
          font-weight: 700;
          color: #00d4aa;
        }
        .stat-unit {
          font-size: 11px;
          color: #7a8394;
          margin-left: 2px;
        }

        /* Divider */
        .divider {
          width: 1px;
          height: 400px;
          background: linear-gradient(to bottom, transparent, rgba(0,212,170,0.15) 30%, rgba(0,212,170,0.15) 70%, transparent);
          flex-shrink: 0;
          align-self: center;
        }

        /* Right panel — form */
        .right-panel {
          width: 420px;
          padding: 60px 48px;
          position: relative;
        }

        .form-card {
          background: #161b22;
          border: 1px solid rgba(255,255,255,0.07);
          border-radius: 16px;
          padding: 40px 36px;
          position: relative;
          overflow: hidden;
          animation: fadeUp 0.5s ease 0.2s both;
        }

        .form-card::before {
          content: '';
          position: absolute; top: 0; left: 0; right: 0; height: 2px;
          background: linear-gradient(90deg, #00d4aa, #0099ff, #00d4aa);
          background-size: 200% 100%;
        }

        /* Corner decorations */
        .corner {
          position: absolute;
          width: 16px; height: 16px;
          border-color: rgba(0,212,170,0.4);
          border-style: solid;
        }
        .corner-tl { top: 8px; left: 8px; border-width: 1px 0 0 1px; }
        .corner-tr { top: 8px; right: 8px; border-width: 1px 1px 0 0; }
        .corner-bl { bottom: 8px; left: 8px; border-width: 0 0 1px 1px; }
        .corner-br { bottom: 8px; right: 8px; border-width: 0 1px 1px 0; }

        .form-logo {
          font-family: 'JetBrains Mono', monospace;
          font-size: 11px;
          color: #00d4aa;
          letter-spacing: 4px;
          margin-bottom: 6px;
          display: flex;
          align-items: center;
          gap: 8px;
        }

        /* Animated logo icon */
        .logo-icon {
          width: 28px; height: 28px;
          border: 1.5px solid #00d4aa;
          border-radius: 6px;
          display: flex; align-items: center; justify-content: center;
          position: relative;
        }
        .logo-icon::after {
          content: '';
          position: absolute;
          width: 6px; height: 6px;
          background: #00d4aa;
          border-radius: 50%;
          animation: nodePulse 2s ease-in-out infinite;
        }

        .form-title {
          font-size: 26px;
          font-weight: 700;
          color: #e8eaf0;
          letter-spacing: 1px;
          margin-bottom: 4px;
        }
        .form-sub {
          font-family: 'JetBrains Mono', monospace;
          font-size: 11px;
          color: #4a5260;
          letter-spacing: 1px;
          margin-bottom: 32px;
        }

        .field-wrap { margin-bottom: 18px; }
        .field-label {
          display: block;
          font-family: 'JetBrains Mono', monospace;
          font-size: 10px;
          color: #4a5260;
          letter-spacing: 2px;
          text-transform: uppercase;
          margin-bottom: 8px;
          transition: color 0.2s;
        }
        .field-label.active { color: #00d4aa; }

        .input-wrap { position: relative; }

        .input-icon {
          position: absolute;
          left: 14px; top: 50%;
          transform: translateY(-50%);
          color: #4a5260;
          display: flex; align-items: center;
          transition: color 0.2s;
          pointer-events: none;
        }
        .input-icon.active { color: #00d4aa; }

        .field-input {
          width: 100%;
          padding: 12px 14px 12px 42px;
          background: #0d1117;
          border: 1px solid rgba(255,255,255,0.08);
          border-radius: 8px;
          color: #e8eaf0;
          font-size: 14px;
          font-family: 'JetBrains Mono', monospace;
          font-weight: 400;
          outline: none;
          transition: border-color 0.2s, box-shadow 0.2s;
        }
        .field-input::placeholder { color: #3a4250; }
        .field-input:focus {
          border-color: rgba(0,212,170,0.4);
          box-shadow: 0 0 0 3px rgba(0,212,170,0.06);
        }

        .eye-btn {
          position: absolute; right: 12px; top: 50%;
          transform: translateY(-50%);
          background: none; border: none;
          cursor: pointer; color: #4a5260;
          display: flex; align-items: center;
          padding: 4px;
          transition: color 0.2s;
        }
        .eye-btn:hover { color: #00d4aa; }

        .error-box {
          display: flex; align-items: center; gap: 10px;
          background: rgba(255,71,87,0.07);
          border: 1px solid rgba(255,71,87,0.25);
          border-radius: 8px;
          padding: 11px 14px;
          margin-bottom: 20px;
          font-family: 'JetBrains Mono', monospace;
          font-size: 12px;
          color: #ff4757;
        }

        .submit-btn {
          width: 100%;
          margin-top: 8px;
          padding: 13px;
          background: linear-gradient(135deg, #00d4aa, #0099ff);
          border: none;
          border-radius: 8px;
          color: #0a0c0f;
          font-family: 'Rajdhani', sans-serif;
          font-weight: 700;
          font-size: 15px;
          letter-spacing: 2px;
          text-transform: uppercase;
          cursor: pointer;
          position: relative;
          overflow: hidden;
          transition: opacity 0.2s, transform 0.1s;
        }
        .submit-btn:hover { opacity: 0.92; transform: translateY(-1px); }
        .submit-btn:active { transform: translateY(0); }
        .submit-btn:disabled { opacity: 0.5; cursor: not-allowed; transform: none; }

        /* Loading spinner in button */
        .btn-spinner {
          display: inline-block;
          width: 14px; height: 14px;
          border: 2px solid rgba(10,12,15,0.3);
          border-top-color: #0a0c0f;
          border-radius: 50%;
          animation: spin 0.7s linear infinite;
          vertical-align: middle;
          margin-right: 8px;
        }

        .submit-btn::before {
          content: '';
          position: absolute; top: 0; left: -100%;
          width: 100%; height: 100%;
          background: linear-gradient(90deg, transparent, rgba(255,255,255,0.15), transparent);
          transition: left 0.4s;
        }
        .submit-btn:hover::before { left: 100%; }

        .form-footer {
          margin-top: 24px;
          padding-top: 20px;
          border-top: 1px solid rgba(255,255,255,0.05);
          display: flex;
          align-items: center;
          justify-content: space-between;
        }
        .status-dot {
          display: flex; align-items: center; gap: 6px;
          font-family: 'JetBrains Mono', monospace;
          font-size: 10px;
          color: #4a5260;
        }
        .status-dot::before {
          content: '';
          width: 6px; height: 6px;
          border-radius: 50%;
          background: #2ed573;
          box-shadow: 0 0 6px #2ed573;
          animation: nodePulse 2s ease-in-out infinite;
        }
        .ver-tag {
          font-family: 'JetBrains Mono', monospace;
          font-size: 10px;
          color: #2a3040;
          letter-spacing: 1px;
        }

        @media (max-width: 900px) {
          .left-panel { display: none; }
          .divider { display: none; }
          .right-panel { width: 100%; max-width: 420px; padding: 24px 16px; }
          .login-bg { padding: 16px; }
        }
      `}</style>

      <div className="login-bg">
        <div className="scanline"/>

        {/* Background nodes */}
        {nodes.map((n,i) => <GridNode key={i} {...n}/>)}

        {/* Right glow */}
        <div style={{
          position:'absolute', right:'-5%', bottom:'10%',
          width:400, height:400,
          background:'radial-gradient(circle, rgba(0,153,255,0.05) 0%, transparent 70%)',
          pointerEvents:'none',
        }}/>

        {/* Left branding panel */}
        <div className="left-panel">
          <div className="brand-tag">Supervision Industrielle</div>

          <h2>
            Contrôle<br/>
            <span>Intelligent</span><br/>
            des Actifs
          </h2>

          <p>
            Monitoring temps réel · Alertes seuils<br/>
            Capteurs IoT · Analyse prédictive
          </p>

          <div className="stat-grid">
            {[
              {label:'Capteurs actifs', val:'128', unit:'unités', delay:'0.3s'},
              {label:'Uptime système',  val:'99.8', unit:'%',     delay:'0.45s'},
              {label:'Alertes / 24h',  val:'3',   unit:'events', delay:'0.6s'},
              {label:'Machines liées', val:'24',  unit:'unités', delay:'0.75s'},
            ].map(s => (
              <div className="stat-item" key={s.label} style={{animationDelay: s.delay}}>
                <div className="stat-label">{s.label}</div>
                <div className="stat-value">{s.val}<span className="stat-unit">{s.unit}</span></div>
              </div>
            ))}
          </div>
        </div>

        {/* Vertical divider */}
        <div className="divider"/>

        {/* Right form panel */}
        <div className="right-panel">
          <div className="form-card">
            {/* Corner decorations */}
            <div className="corner corner-tl"/>
            <div className="corner corner-tr"/>
            <div className="corner corner-bl"/>
            <div className="corner corner-br"/>

            {/* Logo */}
            <div className="form-logo">
              <div className="logo-icon"/>
              INDUSTRIOT
            </div>
            <div className="form-title">Connexion</div>
            <div className="form-sub">// accès sécurisé requis</div>

            {error && (
              <div className="error-box">
                <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                  <circle cx="12" cy="12" r="10"/><line x1="12" y1="8" x2="12" y2="12"/><line x1="12" y1="16" x2="12.01" y2="16"/>
                </svg>
                {error}
              </div>
            )}

            <form onSubmit={handleSubmit}>
              {/* Email */}
              <div className="field-wrap">
                <label className={`field-label ${focused==='email' ? 'active' : ''}`}>Email</label>
                <div className="input-wrap">
                  <div className={`input-icon ${focused==='email' ? 'active' : ''}`}>
                    <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8">
                      <path d="M4 4h16c1.1 0 2 .9 2 2v12c0 1.1-.9 2-2 2H4c-1.1 0-2-.9-2-2V6c0-1.1.9-2 2-2z"/>
                      <polyline points="22,6 12,13 2,6"/>
                    </svg>
                  </div>
                  <input
                    className="field-input"
                    type="email"
                    value={email}
                    onChange={e => setEmail(e.target.value)}
                    onFocus={() => setFocused('email')}
                    onBlur={() => setFocused(null)}
                    placeholder="admin@usine.local"
                    required
                  />
                </div>
              </div>

              {/* Password */}
              <div className="field-wrap">
                <label className={`field-label ${focused==='pwd' ? 'active' : ''}`}>Mot de passe</label>
                <div className="input-wrap">
                  <div className={`input-icon ${focused==='pwd' ? 'active' : ''}`}>
                    <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8">
                      <rect x="3" y="11" width="18" height="11" rx="2" ry="2"/>
                      <path d="M7 11V7a5 5 0 0 1 10 0v4"/>
                    </svg>
                  </div>
                  <input
                    className="field-input"
                    style={{paddingRight: 44}}
                    type={showPwd ? 'text' : 'password'}
                    value={password}
                    onChange={e => setPassword(e.target.value)}
                    onFocus={() => setFocused('pwd')}
                    onBlur={() => setFocused(null)}
                    placeholder="••••••••"
                    required
                  />
                  <button type="button" className="eye-btn" onClick={() => setShowPwd(!showPwd)}>
                    {showPwd ? (
                      <svg viewBox="0 0 24 24" width="15" height="15" fill="none" stroke="currentColor" strokeWidth="1.8">
                        <path d="M17.94 17.94A10.07 10.07 0 0 1 12 20c-7 0-11-8-11-8a18.45 18.45 0 0 1 5.06-5.94"/>
                        <path d="M9.9 4.24A9.12 9.12 0 0 1 12 4c7 0 11 8 11 8a18.5 18.5 0 0 1-2.16 3.19"/>
                        <line x1="1" y1="1" x2="23" y2="23"/>
                      </svg>
                    ) : (
                      <svg viewBox="0 0 24 24" width="15" height="15" fill="none" stroke="currentColor" strokeWidth="1.8">
                        <path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"/>
                        <circle cx="12" cy="12" r="3"/>
                      </svg>
                    )}
                  </button>
                </div>
              </div>

              <button className="submit-btn" type="submit" disabled={loading}>
                {loading && <span className="btn-spinner"/>}
                {loading ? 'Authentification...' : 'Accéder au système'}
              </button>
            </form>

            <div className="form-footer">
              <div className="status-dot">Système opérationnel</div>
              <div className="ver-tag">v2.4.1</div>
            </div>
          </div>
        </div>
      </div>
    </>
  );
}
